USE nexos;

-- Arquiva apenas as questões introdutórias incluídas originalmente no Nexos.
-- As cópias diárias já geradas permanecem no histórico e não são alteradas.
UPDATE Quiz SET publicado=0 WHERE pergunta IN (
  'Qual lei tornou obrigatório o ensino de história e cultura afro-brasileira nas escolas?',
  'Em que ano ocorreu o fim oficial da escravidão no Brasil?',
  'Quais são as categorias de cor ou raça usadas pelo IBGE?',
  'O que é o mito da democracia racial?',
  'Qual lei tornou obrigatório o ensino de História e Cultura Afro-Brasileira nas escolas?',
  'Além da história da África, que outros temas a Lei nº 10.639/2003 inclui no currículo?',
  'Qual lei ampliou a obrigação curricular para incluir também a história e a cultura dos povos indígenas?',
  'Segundo o IBGE, quais categorias aparecem na pergunta de cor ou raça do Censo?',
  'Como o IBGE coleta a informação de cor ou raça no Censo?',
  'Em que ano foi sancionada a Lei nº 10.639, sobre História e Cultura Afro-Brasileira?',
  'Em que ano a Lei nº 11.645 incluiu a temática indígena na legislação curricular?',
  'Qual artigo da Constituição de 1988 reconhece a organização social, os costumes, as línguas, as crenças e as tradições indígenas?',
  'O que a Constituição reconhece aos povos indígenas no artigo 231?',
  'O que estabelece o artigo 68 do Ato das Disposições Constitucionais Transitórias?',
  'Qual data a Lei nº 12.519/2011 instituiu como Dia Nacional de Zumbi e da Consciência Negra?',
  'Qual é o objetivo principal da Lei nº 12.288/2010, conhecida como Estatuto da Igualdade Racial?',
  'A Lei de Cotas (Lei nº 12.711/2012) trata principalmente de reserva de vagas em quais instituições?',
  'A Constituição brasileira classifica o racismo como:',
  'Qual lei define crimes resultantes de preconceito de raça ou de cor?',
  'Segundo o IBGE, a categoria “indígena” no Censo se limita a pessoas que vivem em terras indígenas?',
  'Além da cor ou raça, que informações o Censo pode investigar para pessoas que se declaram indígenas?',
  'Qual alternativa descreve melhor o papel da Lei nº 10.639/2003 na educação?',
  'A Lei nº 11.645/2008 aborda quais histórias e culturas no currículo escolar?',
  'Qual alternativa explica por que a autodeclaração é importante nos dados do IBGE?',
  'O que a Constituição determina sobre o ensino da História do Brasil no artigo 242, §1º?',
  'Qual órgão federal tem atribuições relacionadas à identificação, ao reconhecimento, à delimitação, à demarcação e à titulação das terras quilombolas?',
  'O que significa dizer que uma comunidade quilombola tem direito à titulação coletiva de seu território?',
  'Qual afirmação sobre diversidade étnico-racial está de acordo com a proposta das Leis nº 10.639/2003 e nº 11.645/2008?',
  'No Censo Demográfico 2022, qual categoria de cor ou raça passou a representar a maior parcela da população brasileira, segundo o IBGE?',
  'Qual alternativa corresponde a uma das categorias usadas pelo IBGE no quesito cor ou raça?',
  'A proteção constitucional aos povos indígenas inclui o respeito a quais aspectos de sua vida coletiva?'
);

-- Banco autoral: alternativas próximas em tema e formato; referências oficiais são exibidas após a resposta.
INSERT INTO Quiz(pergunta,opcao_a,opcao_b,opcao_c,opcao_d,correta,fonte)
SELECT n.pergunta,n.opcao_a,n.opcao_b,n.opcao_c,n.opcao_d,n.correta,n.fonte
FROM (
  SELECT 'A Lei nº 10.639/2003 alterou a LDB para incluir a temática afro-brasileira. Qual dispositivo passou a tratar dessa obrigatoriedade?' AS pergunta,'Art. 26-A, sobre currículo da educação básica' AS opcao_a,'Art. 12, sobre proposta pedagógica' AS opcao_b,'Art. 70, sobre despesas de manutenção' AS opcao_c,'Art. 87, sobre a década da educação' AS opcao_d,0 AS correta,'https://www.planalto.gov.br/ccivil_03/leis/2003/l10.639.htm' AS fonte
  UNION ALL SELECT 'Pela redação da Lei nº 10.639/2003, em quais componentes o estudo deve receber atenção especial?','História e Geografia, exclusivamente','Educação Artística, Literatura e História brasileiras','Sociologia e Filosofia, exclusivamente','Língua Portuguesa e Matemática',1,'https://www.planalto.gov.br/ccivil_03/leis/2003/l10.639.htm'
  UNION ALL SELECT 'Que mudança a Lei nº 11.645/2008 fez no art. 26-A da LDB?','Substituiu o ensino afro-brasileiro por conteúdo indígena','Restringiu a temática às escolas indígenas','Acrescentou história e cultura indígenas à temática já prevista','Criou uma disciplina separada para cada povo',2,'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/lei/l11645.htm'
  UNION ALL SELECT 'A Lei nº 10.639/2003 incluiu qual data no calendário escolar como Dia Nacional da Consciência Negra?','13 de maio','19 de abril','21 de março','20 de novembro',3,'https://www.planalto.gov.br/ccivil_03/leis/2003/l10.639.htm'
  UNION ALL SELECT 'O art. 242, §1º, da Constituição orienta que o ensino da História do Brasil considere:','As contribuições das diferentes culturas e etnias para a formação do povo brasileiro','Apenas a formação política após 1889','Somente documentos produzidos pelo governo federal','A história regional como substituta da história nacional',0,'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
  UNION ALL SELECT 'Qual conjunto corresponde aos direitos reconhecidos pelo art. 231 da Constituição aos povos indígenas?','Autonomia para criar estados independentes e emitir moeda','Organização social, costumes, línguas, crenças, tradições e direitos originários sobre terras tradicionalmente ocupadas','Propriedade individual de toda terra ocupada por qualquer período','Representação parlamentar reservada em todas as casas legislativas',1,'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
  UNION ALL SELECT 'Segundo o art. 231, §2º, da Constituição, as terras tradicionalmente ocupadas pelos povos indígenas destinam-se a:','Exploração mineral exclusiva por empresas comunitárias','Propriedade privada individual com livre alienação','Posse permanente e usufruto exclusivo das riquezas do solo, rios e lagos','Uso temporário definido pelos municípios',2,'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
  UNION ALL SELECT 'O art. 68 do ADCT reconhece às comunidades remanescentes de quilombos que estejam ocupando suas terras:','Concessão de uso por prazo renovável','Direito de consulta sem previsão de titulação','Preferência em programas habitacionais','Propriedade definitiva, com dever estatal de emitir os títulos',3,'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
  UNION ALL SELECT 'No Decreto nº 4.887/2003, a caracterização de comunidade quilombola considera, entre outros elementos:','Autodefinição, trajetória histórica própria e relações territoriais específicas','Certificação individual de descendência emitida por universidade','Residência contínua em área rural desde antes de 1888','Registro exclusivamente em cartório municipal',0,'https://planalto.gov.br/ccivil_03/decreto/2003/d4887.htm'
  UNION ALL SELECT 'Segundo o Decreto nº 4.887/2003, a medição e demarcação das terras quilombolas devem considerar critérios de:','Ocupação produtiva individual registrada em matrícula urbana','Territorialidade indicados pela própria comunidade','Limites municipais anteriores à Constituição de 1988','Valor de mercado sem participação comunitária',1,'https://planalto.gov.br/ccivil_03/decreto/2003/d4887.htm'
  UNION ALL SELECT 'No procedimento federal de regularização de territórios quilombolas, qual órgão conduz a titulação em áreas sob sua atribuição?','IBGE','IPHAN','INCRA','INEP',2,'https://www.gov.br/incra/pt-br/assuntos/governanca-fundiaria/quilombolas/'
  UNION ALL SELECT 'A Convenção nº 169 da OIT prevê consulta a povos indígenas e tribais diante de medidas que os afetem diretamente. Essa consulta deve ser:','Restrita a decisões sobre educação básica','Realizada somente depois da execução da medida','Feita apenas por votação individual em urna nacional','Prévia, livre e informada, por meio de instituições representativas',3,'https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2004/decreto/d5051.htm'
  UNION ALL SELECT 'No quesito cor ou raça do Censo Demográfico, a metodologia do IBGE baseia-se principalmente em:','Autodeclaração segundo as categorias investigadas','Classificação do recenseador por fotografia','Documentos de nascimento dos pais','Exame genético durante a entrevista',0,'https://educa.ibge.gov.br/jovens/materias-especiais/18319-cor-ou-raca.html'
  UNION ALL SELECT 'No Censo 2022, a população parda correspondia a aproximadamente:','10,2%, menor proporção entre as categorias','45,3% da população, maior proporção entre as categorias de cor ou raça','56,1%, sem alteração em relação ao Censo anterior','38,4%, abaixo da população branca e preta somadas',1,'https://agenciadenoticias.ibge.gov.br/agencia-noticias/2012-agencia-de-noticias/noticias/38719-censo-2022-pela-primeira-vez-desde-1991-a-maior-parte-da-populacao-do-brasil-se-declara-parda'
  UNION ALL SELECT 'Por que a categoria estatística “pardo” não deve ser tratada como uma identidade cultural única e homogênea?','Porque se refere somente a descendentes de imigrantes recentes','Porque o IBGE não utiliza essa categoria nos censos','Porque reúne pessoas com experiências e trajetórias diversas','Porque é definida por idioma, não por autodeclaração',2,'https://educa.ibge.gov.br/jovens/materias-especiais/18319-cor-ou-raca.html'
  UNION ALL SELECT 'Qual distinção é mais adequada entre raça e etnia em estudos sociais?','São conceitos idênticos e medidos sempre pela mesma pergunta','Raça descreve idioma e religião, enquanto etnia descreve somente aparência','Etnia é definida apenas pela nacionalidade legal','Raça é uma classificação social; etnia pode envolver pertencimento, história, cultura e vínculos compartilhados',3,'https://www.ibge.gov.br/estatisticas/sociais/populacao/22827-censo-demografico-2022.html'
  UNION ALL SELECT 'No debate sociológico brasileiro, a ideia de “democracia racial” é criticada sobretudo porque:','A suposta harmonia pode ocultar desigualdades raciais e discriminações persistentes','A Constituição proíbe pesquisas sobre desigualdade','O conceito afirma que o Brasil não tem diversidade','A expressão é o nome oficial de uma política pública',0,'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12288.htm'
  UNION ALL SELECT 'O Estatuto da Igualdade Racial define desigualdade racial como:','Qualquer diferença regional de renda, sem relação com raça','Diferença no acesso a bens, serviços e oportunidades entre grupos raciais','Desigualdade restrita à representação eleitoral','Diferença individual de escolaridade sem dimensão social',1,'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12288.htm'
  UNION ALL SELECT 'A Lei nº 7.716/1989 tipifica crimes de discriminação ou preconceito relacionados, entre outros motivos, a:','Idioma estrangeiro, sotaque ou local de nascimento, exclusivamente','Renda, escolaridade, profissão ou região de moradia','Raça, cor, etnia, religião ou procedência nacional','Opinião política, idade ou estado civil, exclusivamente',2,'https://www.planalto.gov.br/ccivil_03/leis/l7716.htm'
  UNION ALL SELECT 'A Lei nº 12.711/2012 disciplina principalmente a reserva de vagas em:','Cursos livres de organizações da sociedade civil','Todas as escolas privadas de educação básica','Concursos de todas as empresas públicas e privadas','Instituições federais de educação superior e de ensino técnico de nível médio',3,'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12711.htm'
  UNION ALL SELECT 'Qual foi o objetivo central da Lei Eusébio de Queirós, promulgada em 1850?','Reprimir o tráfico transatlântico de pessoas escravizadas para o Brasil','Declarar livres todas as pessoas escravizadas com mais de 60 anos','Abolir a escravidão em todo o território brasileiro','Criar matrícula obrigatória de pessoas libertas',0,'https://www2.camara.leg.br/legin/fed/leimp/1824-1899/lei-581-4-setembro-1850-559820-norma-pl.html'
  UNION ALL SELECT 'A Lei do Ventre Livre, de 1871, determinava que os filhos de mulheres escravizadas nascidos após a lei seriam:','Libertos apenas após o serviço militar obrigatório','Livres, embora houvesse condições legais de tutela e prestação de serviços até certa idade','Mantidos escravizados até os 21 anos sem exceção','Imediatamente entregues à guarda de escolas públicas',1,'https://www.planalto.gov.br/ccivil_03/leis/lim/lim2040.htm'
  UNION ALL SELECT 'Qual característica distingue a Lei dos Sexagenários (1885) de uma abolição geral?','Proibia o tráfico interno entre províncias','Libertava todas as pessoas escravizadas sem condições','Previa liberdade condicionada para pessoas escravizadas de idade avançada e obrigações previstas na lei','Reconhecia voto pleno a todos os libertos',2,'https://www.planalto.gov.br/ccivil_03/leis/lim/lim3270.htm'
  UNION ALL SELECT 'A Lei Áurea, assinada em 13 de maio de 1888, teve como efeito jurídico imediato:','Instituir voto universal sem restrições de gênero ou renda','Criar indenização geral paga pelo Estado às pessoas libertas','Distribuir terras a todas as famílias libertas','Declarar extinta a escravidão no Brasil, sem instituir um programa amplo de integração social',3,'https://www.planalto.gov.br/ccivil_03/leis/lim/lim3353.htm'
  UNION ALL SELECT 'A Revolta dos Malês, ocorrida em Salvador em 1835, destacou-se pela participação de:','Africanos muçulmanos, incluindo pessoas escravizadas e libertas','Oficiais da Guarda Nacional contrários à República','Imigrantes europeus que reivindicavam voto censitário','Trabalhadores livres organizados contra a vacinação obrigatória',0,'https://www.ba.gov.br/comunicacao/noticias/2025-02/365005/arquivo-publico-da-bahia-preserva-documentos-da-revolta-dos-males'
  UNION ALL SELECT 'A Revolta da Chibata, em 1910, teve entre suas reivindicações centrais:','Restauração do Poder Moderador','Fim dos castigos físicos na Marinha e melhores condições para os marinheiros','Extinção do serviço naval e distribuição de navios','Criação de uma lei nacional de reforma agrária',1,'https://web.arquivoestado.sp.gov.br/exposicao_chibata/index.php'
  UNION ALL SELECT 'O Cais do Valongo, reconhecido como Patrimônio Mundial pela UNESCO, está ligado:','À primeira imigração japonesa em massa para o Brasil','À chegada da corte portuguesa em 1808 e à abertura dos portos','Ao desembarque de africanos escravizados no Rio de Janeiro durante o tráfico atlântico','À exportação de café no século XX',2,'https://whc.unesco.org/en/decisions/6907/'
  UNION ALL SELECT 'A roda de capoeira foi registrada pelo Iphan, em 2008, no Livro de:','Registro dos Objetos Arqueológicos','Registro dos Lugares','Registro dos Saberes','Registro das Formas de Expressão',3,'https://bcr.iphan.gov.br/acoes-de-salvaguarda/registro-da-roda-de-capoeira-como-patrimonio-cultural-do-brasil/'
  UNION ALL SELECT 'O Samba de Roda do Recôncavo Baiano foi proclamado Obra-Prima do Patrimônio Oral e Imaterial da Humanidade pela UNESCO em:','2005','2003','2001','2010',0,'https://www.gov.br/iphan/pt-br/assuntos/noticias/samba-de-roda-no-reconcavo-baiano-completa-18-anos-como-patrimonio-cultural-do-brasil/'
  UNION ALL SELECT 'O Ofício das Baianas de Acarajé foi registrado pelo Iphan no Livro de:','Registro das Celebrações','Registro dos Saberes','Registro dos Lugares','Registro das Formas de Expressão',1,'https://bcr.iphan.gov.br/bens-culturais/oficio-das-baianas-de-acaraje/'
  UNION ALL SELECT 'Na política de patrimônio imaterial, o registro de um bem cultural tem como foco principal:','Impedir mudanças na forma como a comunidade realiza a tradição','Transformar a prática em propriedade exclusiva do Estado','Reconhecer e apoiar a continuidade de práticas e conhecimentos culturais','Substituir a transmissão comunitária por certificação escolar',2,'https://www.gov.br/iphan/pt-br/patrimonio-cultural/patrimonio-imaterial'
  UNION ALL SELECT 'Qual alternativa diferencia melhor patrimônio material e imaterial?','Material tem valor artístico; imaterial tem apenas valor econômico','Material é sempre privado; imaterial pertence exclusivamente à União','Material é antigo; imaterial é necessariamente recente','Material abrange bens físicos; imaterial envolve práticas, saberes, celebrações e formas de expressão',3,'https://www.gov.br/iphan/pt-br/patrimonio-cultural/patrimonio-imaterial'
  UNION ALL SELECT 'Ao estudar a abolição, o conceito de “pós-abolição” ajuda a investigar:','Disputas, políticas e desigualdades que continuaram após 1888','Somente o período entre a Lei do Ventre Livre e a Lei Áurea','A passagem da Monarquia à República sem relações raciais','Apenas o tráfico atlântico anterior ao século XIX',0,'https://www.gov.br/arquivonacional/pt-br'
  UNION ALL SELECT 'Uma política de ação afirmativa se distingue de uma política universal porque:','Substitui todos os direitos sociais por benefícios individuais','Busca enfrentar barreiras específicas e desigualdades que atingem determinados grupos','É necessariamente temporária em qualquer formato jurídico','Considera somente renda e nunca outros critérios',1,'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12288.htm'
  UNION ALL SELECT 'A análise interseccional das desigualdades considera que:','A classe social elimina os efeitos de raça e gênero','Cada forma de desigualdade deve ser analisada sem relação com as demais','Eixos como raça, gênero e classe podem se combinar e produzir experiências específicas','Identidades individuais explicam sozinhas as estruturas sociais',2,'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12288.htm'
  UNION ALL SELECT 'Por que cruzar registros oficiais com relatos orais e fontes comunitárias pode ser importante na pesquisa histórica?','Porque fontes comunitárias dispensam contextualização','Porque relatos orais sempre substituem documentos escritos','Porque documentos oficiais não podem ser usados por historiadores','Amplia perspectivas e permite confrontar silêncios e limites de cada tipo de fonte',3,'https://www.gov.br/arquivonacional/pt-br'
) AS n
LEFT JOIN Quiz existente ON existente.pergunta=n.pergunta
WHERE existente.id_quiz IS NULL;
